// @whimtex-effect Learn/Final Tint
// @control(_Opacity)
// @param float _Opacity = 1 [0 .. 1]
// @param color _Tint = #FFFFFF
// @param float _Brightness = 1 [0 .. ~3]


float LearnHash(float2 p){ return frac(sin(dot(p,float2(127.1,311.7)))*43758.5453); }
float LearnNoise(float2 p, float seed){
 fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float LearnFbm(float2 p,float seed){
 fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 s.fractal_type=FNL_FRACTAL_FBM;s.octaves=3;s.gain=.42;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float2 LearnRotate(float2 p,float angle){float c=cos(radians(angle)),s=sin(radians(angle));return float2(c*p.x-s*p.y,s*p.x+c*p.y);}
float LearnEdge(float d,float softness){float w=max(fwidth(d),max(softness,.00001));return 1-smoothstep(-w,w,d);}
float LearnGauss(float x){return exp(-x*x);}

float4 ApplyFX(float2 uv,float4 color){

return float4(color.rgb*_Tint.rgb*_Brightness,color.a*_Tint.a*_Opacity);
}

// @whimtex-effect Learn/Woven Hatching
// @control(_Opacity)
// @param float _Opacity = 1 [0 .. 1]
// @group(Placement)
// @param point _Center = (0.5, 0.5)
// @param float2 _Scale = (1, 1)
// @param float _Angle = 0 [-180 .. 180]
// @endgroup
// @group(Hatching; _Style)
// @param hidden enum _Style = Cross {Cross:0, Diagonal:1, Cells:2}
// @param float _Spacing = 0.028 [0.005 .. 0.15]
// @param float _Width = 0.12 [0.01 .. 0.45]
// @param float _Roughness = 0.7 [0 .. 1]
// @param float _CellSize = 0.17 [0.04 .. 0.4]
// @param float _Seed = 17 [1 .. ~5000]
// @param color _Paper = #FFFFFF
// @param color _Ink = #242424
// @endgroup

float LearnHash(float2 p){ return frac(sin(dot(p,float2(127.1,311.7)))*43758.5453); }
float LearnNoise(float2 p, float seed){
 fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float LearnFbm(float2 p,float seed){
 fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 s.fractal_type=FNL_FRACTAL_FBM;s.octaves=3;s.gain=.42;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float2 LearnRotate(float2 p,float angle){float c=cos(radians(angle)),s=sin(radians(angle));return float2(c*p.x-s*p.y,s*p.x+c*p.y);}
float LearnEdge(float d,float softness){float w=max(fwidth(d),max(softness,.00001));return 1-smoothstep(-w,w,d);}
float LearnGauss(float x){return exp(-x*x);}

float4 SampleHatching(float2 uv,float4 color){
float2 p=LearnRotate(LayerToLocal(uv)-_Center,-_Angle)/max(abs(_Scale),.001);

float2 q=LearnRotate(p,45);float ink=0;
if(_Style>1.5){
 float2 lattice=p/_CellSize;float2 cell=floor(lattice);float best=1e6;float2 chosen=0,center=0;
 for(int y=-1;y<=1;y++)for(int x=-1;x<=1;x++){
  float2 id=cell+float2(x,y);float2 c=id+.5+(float2(LearnHash(id+_Seed),LearnHash(id+31+_Seed))-.5)*.7;
  float d=dot(lattice-c,lattice-c);if(d<best){best=d;chosen=id;center=c;}
 }
 q=LearnRotate((lattice-center)*_CellSize,LearnHash(chosen+_Seed+13)*180);
}
float grain=LearnNoise(p*65,_Seed);float bend=(LearnNoise(p*7,_Seed+1)-.5)*_Roughness*.32;
float stripe=abs(frac(q.x/_Spacing+bend)-.5);
float aa=max(0.5*fwidth(q.x/_Spacing),.005);
ink=1-smoothstep(_Width-aa,_Width+aa,stripe);
if(_Style<.5){
 float other=abs(frac(q.y/_Spacing-bend)-.5);
 ink=max(ink,(1-smoothstep(_Width-aa,_Width+aa,other))*.85);
}
ink*=lerp(1,grain*.8+.3,_Roughness);
if(_Style<1.5){
 float fine=abs(frac((q.x+q.y*.06)/(_Spacing*.42)+bend*.5)-.5);
 ink=max(ink,(1-smoothstep(_Width*.5-aa,_Width*.5+aa,fine))*grain*.22);
}
return float4(lerp(_Paper.rgb,_Ink.rgb,saturate(ink)),_Opacity);
}

// Four procedural subpixel samples retain fine ink coverage at the reduced canvas size.
float4 ApplyFX(float2 uv, float4 color) {
 float2 d=0.25*_CanvasSize.zw;
 return 0.25*(SampleHatching(uv+float2(-d.x,-d.y),color)+SampleHatching(uv+float2(d.x,-d.y),color)+SampleHatching(uv+float2(-d.x,d.y),color)+SampleHatching(uv+d,color));
}
